#include <iostream>

int main() {
    const int fichas = 18;
    int capacidad = 5;
    const bool acepta_sobrantes = true;
    if ((fichas < 0) || (fichas > 30) || (capacidad < 1) || (capacidad > 6)) {
        std::cout << "Datos invalidos";
    } else if (fichas == 0) {
        std::cout << "Sin trabajo";
    } else {
        const int grupos = fichas / capacidad;
        const int sobrantes = fichas % capacidad;
        if (sobrantes == 0) {
            std::cout << "Grupos: " << grupos;
        } else if (acepta_sobrantes) {
            std::cout << "Grupos: " << grupos << "\n";
            std::cout << "Sobrantes: " << sobrantes;
        } else {
            std::cout << "Reparto pendiente";
        }
    }
    return 0;
}

